import Domain
import Foundation
@testable import AudioInfrastructure
import Testing

// MARK: - Helpers

private func makeMicBuffer(
    sampleCount: Int = 256,
    sampleRate: Double = 16000,
    timestamp: TimeInterval = 0.0
) -> TaggedAudioBuffer {
    let samples = [Float](repeating: 0.1, count: sampleCount)
    let raw = AudioBuffer(sampleRate: sampleRate, channelCount: 1, samples: samples, timestamp: timestamp)
    return TaggedAudioBuffer(buffer: raw, track: .microphone, timestamp: timestamp)
}

private func makeFarEndBuffer(
    sampleCount: Int = 256,
    sampleRate: Double = 16000,
    timestamp: TimeInterval = 0.0
) -> TaggedAudioBuffer {
    let samples = [Float](repeating: 0.05, count: sampleCount)
    let raw = AudioBuffer(sampleRate: sampleRate, channelCount: 1, samples: samples, timestamp: timestamp)
    return TaggedAudioBuffer(buffer: raw, track: .system, timestamp: timestamp)
}

// MARK: - Echo-fixture helpers

/// Deterministic pseudo-voice far-end: sum of sinusoids with a slow amplitude envelope.
/// Seeded completely by the frame index — no randomness, no Date().
///
/// - Parameters:
///   - frameIndex: Zero-based frame number, used to compute absolute sample offset.
///   - frameSize: Samples per frame (default 256 at 16 kHz = 16 ms).
private func makeFarEndVoice(frameIndex: Int, frameSize: Int = 256) -> [Float] {
    let sampleRate: Double = 16000
    let offset = frameIndex * frameSize
    return (0 ..< frameSize).map { i in
        let t = Double(offset + i) / sampleRate
        // Three-partial voice: fundamental 200 Hz + 400 Hz + 600 Hz, modulated at 3 Hz.
        let envelope = Float(0.5 + 0.5 * sin(2 * .pi * 3.0 * t))
        let signal = Float(
            sin(2 * .pi * 200 * t) * 0.5 +
            sin(2 * .pi * 400 * t) * 0.3 +
            sin(2 * .pi * 600 * t) * 0.2
        )
        return envelope * signal * 0.6 // amplitude ~0.6 before 16-bit quantisation
    }
}

}

/// Independent near-end "speech": different partials (300 Hz, 500 Hz, 700 Hz).
private func makeNearEndSpeech(frameIndex: Int, frameSize: Int = 256) -> [Float] {
    let sampleRate: Double = 16000
    let offset = frameIndex * frameSize
    return (0 ..< frameSize).map { i in
        let t = Double(offset + i) / sampleRate
        let envelope = Float(0.5 + 0.5 * cos(2 * .pi * 2.0 * t))
        let signal = Float(
            sin(2 * .pi * 300 * t) * 0.4 +
            sin(2 * .pi * 500 * t) * 0.4 +
            sin(2 * .pi * 700 * t) * 0.2
        )
        return envelope * signal * 0.3
    }
}

/// Mixes near-end speech with an attenuated, delayed copy of the far-end (the echo).
///
/// - Parameters:
///   - speech: Clean near-end speech samples.
///   - farEndSamples: Far-end reference for this frame.
///   - prevFarEndSamples: Far-end samples from the previous frame (for cross-frame delay).
///   - echoDelaySamples: Echo delay in samples. Must be < frameSize so it spans at most
///     one frame boundary — keeps history management simple.
///   - echoGain: Attenuation of the echoed signal relative to far-end (default 0.4).
private func mixEcho(
    speech: [Float],
    farEndSamples: [Float],
    prevFarEndSamples: [Float],
    echoDelaySamples: Int,
    echoGain: Float = 0.4
) -> [Float] {
    let n = speech.count
    return (0 ..< n).map { i in
        // Delayed far-end index: look back `echoDelaySamples` samples.
        let delayedFarEnd: Float
        let srcIdx = i - echoDelaySamples
        if srcIdx >= 0 {
            delayedFarEnd = farEndSamples[srcIdx]
        } else {
            // Wrap into previous frame.
            let prevIdx = prevFarEndSamples.count + srcIdx
            delayedFarEnd = prevIdx >= 0 ? prevFarEndSamples[prevIdx] : 0
        }
        return speech[i] + delayedFarEnd * echoGain
    }
}

/// RMS energy of a sample array. Returns 0 for an empty array.
private func rmsEnergy(_ samples: [Float]) -> Double {
    guard !samples.isEmpty else { return 0 }
    let sum = samples.reduce(0.0) { $0 + Double($1) * Double($1) }
    return (sum / Double(samples.count)).squareRoot()
}

