}

/// Feeds `frameCount` synthesized frame pairs through `processor` and collects outputs.
/// Returns the output buffers for each frame.
private func runEchoFixture(
    processor: AECProcessorActor,
    frameCount: Int,
    frameSize: Int = 256,
    echoDelaySamples: Int = 128
) async -> [[Float]] {
    var outputs: [[Float]] = []
    var prevFarEnd = [Float](repeating: 0, count: frameSize)

    for idx in 0 ..< frameCount {
        let farEndSamples = makeFarEndVoice(frameIndex: idx, frameSize: frameSize)
        let speech = makeNearEndSpeech(frameIndex: idx, frameSize: frameSize)
        let nearWithEcho = mixEcho(
            speech: speech,
            farEndSamples: farEndSamples,
            prevFarEndSamples: prevFarEnd,
            echoDelaySamples: echoDelaySamples
        )
        prevFarEnd = farEndSamples

        let ts = Double(idx) * Double(frameSize) / 16000
        let micRaw = AudioBuffer(sampleRate: 16000, channelCount: 1, samples: nearWithEcho, timestamp: ts)
        let mic = TaggedAudioBuffer(buffer: micRaw, track: .microphone, timestamp: ts)
        let farRaw = AudioBuffer(sampleRate: 16000, channelCount: 1, samples: farEndSamples, timestamp: ts)
        let farEnd = TaggedAudioBuffer(buffer: farRaw, track: .system, timestamp: ts)

        let result = await processor.process(mic: mic, farEnd: farEnd)
        outputs.append(result.buffer.samples)
    }
    return outputs
}

