import Domain
import Foundation
import Logging
import speex

// MARK: - SpeexResources

/// Owns the two Speex C heap allocations so they are freed deterministically
/// in `deinit` — even if `stop()` is never called on the actor.
private final class SpeexResources {
    let echo: OpaquePointer
    let pp: OpaquePointer

    init?(frameSize: Int32, filterLength: Int32, sampleRate: Int32) {
        guard let e = speex_echo_state_init(frameSize, filterLength),
              let p = speex_preprocess_state_init(frameSize, sampleRate)
        else { return nil }
        // Link preprocessor to echo state for residual echo suppression.
        // speex_preprocess_ctl SPEEX_PREPROCESS_SET_ECHO_STATE stores the ptr
        // directly (st->echo_state = (SpeexEchoState*)ptr), so pass the opaque
        // pointer cast to UnsafeMutableRawPointer — not a pointer to a pointer.
        speex_preprocess_ctl(p, SPEEX_PREPROCESS_SET_ECHO_STATE, UnsafeMutableRawPointer(e))
        echo = e
        pp = p
    }

    deinit {
        speex_echo_state_destroy(echo)
        speex_preprocess_state_destroy(pp)
    }
}

// MARK: - AECProcessorActor

/// Applies SpeexDSP acoustic echo cancellation to mic audio using the far-end
/// (system audio) stream as the echo reference.
///
/// ## Thread Safety
/// All mutable state (`resources`, `stopped`) is isolated to the actor.
/// No callbacks or external threads access this state.
///
/// ## Error Translation
/// No external error types are thrown -- Speex operates via C function calls that
/// return output values. An uninitialized state (after `stop()`) causes pass-through
/// rather than an error.
///
/// ## Frame Sizing
/// Speex requires fixed-size Int16 frames. Input buffers are chunked into
/// `frameSize` windows; leftovers carry across calls in `remainder`.
///
/// ## Memory Safety
/// Speex C heap allocations are owned by `SpeexResources` and freed in its `deinit`,
/// guaranteeing no leak even if `stop()` is never called.
public actor AECProcessorActor: MicAECProcessor {
    private let aecQueue = DispatchSerialQueue(label: "app.the-record.aec", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        aecQueue.asUnownedSerialExecutor()
    }

    // MARK: - Private State

    /// Wraps the two Speex C allocations; `nil` after `stop()` or failed init.
    private var resources: SpeexResources?

    private let frameSize: Int32
    private let filterLength: Int32
    private let sampleRate: Int32

    private let logger = AppLogger.for(category: "AECProcessor")

    // MARK: - Pre-allocated frame buffers

    private var micInt16: [Int16]
    private var farInt16: [Int16]
    private var outInt16: [Int16]
    private var outFloat: [Float]

    // MARK: - Remainder buffer for inter-call chunking

    /// Carries sub-frame leftover samples from the previous call.
    /// Prepended to the next call's input so no samples are ever discarded.
    private var remainder: [Float] = []

    // MARK: - Public State

    /// `true` while the actor is processing; set to `false` after `stop()`.
    public private(set) var isActive = true

    // MARK: - Init

    public init(frameSize: Int32 = 256, filterLength: Int32 = 4096, sampleRate: Int32 = 16000) {
        self.frameSize = frameSize
        self.filterLength = filterLength
        self.sampleRate = sampleRate

        let count = Int(frameSize)
        micInt16 = [Int16](repeating: 0, count: count)
        farInt16 = [Int16](repeating: 0, count: count)
        outInt16 = [Int16](repeating: 0, count: count)
        outFloat = [Float](repeating: 0, count: count)

        resources = SpeexResources(
            frameSize: frameSize,
            filterLength: filterLength,
            sampleRate: sampleRate
        )
        if resources == nil {
            isActive = false
            logger.error("AECProcessorActor: Speex init failed -- AEC is inactive (pass-through mode)")
        }
    }

    // MARK: - Public API

    public func process(mic: TaggedAudioBuffer, farEnd: TaggedAudioBuffer) -> TaggedAudioBuffer {
        guard let res = resources else {
            if !isActive {
                logger.warning("AECProcessorActor.process() called after stop() -- returning mic pass-through")
            } else {
                logger.warning("AECProcessorActor.process() called with nil resources -- returning mic pass-through")
            }
            return passThrough(mic: mic)
        }

        let count = Int(frameSize)

        // Prepend leftover samples from the previous call, then loop over full
        // 256-sample chunks. Speex requires exactly frameSize samples per call;
        // the chunking loop ensures every input sample is eventually processed.
        var accumulated = remainder + mic.buffer.samples
        var allProcessed: [Float] = []
        allProcessed.reserveCapacity(accumulated.count)

        while accumulated.count >= count {
            let chunk = Array(accumulated.prefix(count))
            accumulated.removeFirst(count)

            fillInt16(&micInt16, from: chunk, frameSize: count)
            fillInt16(&farInt16, from: farEnd.buffer.samples, frameSize: count)
            for i in 0 ..< count { outInt16[i] = 0 }

            speex_echo_cancellation(res.echo, &micInt16, &farInt16, &outInt16)
            speex_preprocess_run(res.pp, &outInt16)

            fillFloat32(&outFloat, from: outInt16)
            allProcessed.append(contentsOf: outFloat)
        }

        // Carry sub-frame leftovers into the next call.
        remainder = accumulated

        let outBuffer = AudioBuffer(
            sampleRate: Double(sampleRate),
            channelCount: 1,
            samples: allProcessed,
            timestamp: mic.buffer.timestamp
        )
        return TaggedAudioBuffer(buffer: outBuffer, track: .microphone, timestamp: mic.timestamp)
    }

    public func stop() {
        guard isActive else { return }
        isActive = false
        resources = nil  // triggers SpeexResources.deinit
        remainder = []   // discard buffered remainder -- session is ending
        logger.info("AECProcessorActor stopped, Speex resources released")
    }

    // MARK: - Private Helpers

    private func passThrough(mic: TaggedAudioBuffer) -> TaggedAudioBuffer {
        TaggedAudioBuffer(buffer: mic.buffer, track: .microphone, timestamp: mic.timestamp)
    }

    private func fillInt16(_ dest: inout [Int16], from src: [Float], frameSize: Int) {
        let limit = min(src.count, frameSize)
        for i in 0 ..< limit {
            dest[i] = Int16(clamping: Int(src[i] * 32767))
        }
        if limit < frameSize {
            for i in limit ..< frameSize { dest[i] = 0 }
        }
    }

    private func fillFloat32(_ dest: inout [Float], from src: [Int16]) {
        for i in 0 ..< src.count {
            dest[i] = Float(src[i]) / 32767.0
        }
    }
}
